// Writes supabase/setup.sql: every migration in order, then the seed.
// Paste that one file into Supabase → SQL Editor on a fresh project.
//   npm run db:bundle
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const migrations = readdirSync(resolve(here, "migrations"))
  .filter((f) => f.endsWith(".sql"))
  .sort();

const parts = [
  "-- Open Sky Food Park: full database setup for a NEW Supabase project.",
  "-- Generated by supabase/bundle.mjs from supabase/migrations/*.sql and supabase/seed.sql. Do not edit by hand.",
  "-- Run once in Supabase -> SQL Editor. For an existing project, run only the migrations it has not had yet.",
  "",
  ...migrations.flatMap((f) => [`-- ================================================================ ${f}`, readFileSync(resolve(here, "migrations", f), "utf8"), ""]),
  "-- ================================================================ seed.sql",
  readFileSync(resolve(here, "seed.sql"), "utf8"),
];

writeFileSync(resolve(here, "setup.sql"), parts.join("\n"));
console.log(`setup.sql: ${migrations.join(", ")} + seed.sql`);
